 public class Trend:FrameworkElement {
  public readonly List<double> CPU=new List<double>(),RAM=new List<double>();
  public void Add(double c,double r){CPU.Add(Math.Max(0,c));RAM.Add(r);if(CPU.Count>60){CPU.RemoveAt(0);RAM.RemoveAt(0);}InvalidateVisual();}
  protected override void OnRender(DrawingContext d){base.OnRender(d);double w=ActualWidth,h=ActualHeight;for(int i=0;i<5;i++)d.DrawLine(new Pen(new SolidColorBrush(Color.FromRgb(39,56,77)),1),new Point(0,h*i/4),new Point(w,h*i/4));Draw(d,CPU,"#71E4C4",w,h);Draw(d,RAM,"#A99BFF",w,h);}
  void Draw(DrawingContext d,List<double> values,string hex,double w,double h){var pen=new Pen((Brush)new BrushConverter().ConvertFromString(hex),2.5);for(int i=1;i<values.Count;i++)d.DrawLine(pen,new Point(w*(i-1)/59,h*(1-values[i-1]/100)),new Point(w*i/59,h*(1-values[i]/100)));}
 }
