  void Save(){settings.Comfy=comfy.Text.Trim();settings.Model=manualModel.Text.Trim();settings.Folder=folder.Text;settings.AutoClean=auto.IsChecked==true;settings.ProtectComfy=protect.IsChecked==true;settings.Tray=trayOption.IsChecked==true;settings.Minutes=interval.SelectedItem is int?(int)interval.SelectedItem:30;settings.Save();}
  void ChooseFolder(TextBox field){using(var d=new Forms.FolderBrowserDialog{Description="Выберите папку",SelectedPath=Directory.Exists(field.Text)?field.Text:"",ShowNewFolderButton=false})if(d.ShowDialog()==Forms.DialogResult.OK)field.Text=d.SelectedPath;}
  void ChooseAll(DataGrid grid,bool value){Commit(grid);var rows=grid.ItemsSource as List<FileRow>;if(rows!=null){foreach(var r in rows)r.Selected=value;grid.Items.Refresh();}}
  async Task Scan(){Select(1);status.Text="Сканирование временных файлов…";var rows=await Task.Run(()=>Core.Scan());cleanGrid.ItemsSource=rows;cleanSummary.Text=rows.Count+" файлов • "+Core.Size(rows.Sum(x=>x.Bytes));status.Text="Сканирование завершено. Проверьте список.";}
  async Task Clean(){Commit(cleanGrid);var rows=cleanGrid.ItemsSource as List<FileRow>;if(rows==null){await Scan();return;}int count=rows.Count(x=>x.Selected);if(count==0)return;if(!Confirm("Окончательно удалить "+count+" выбранных временных файлов?"))return;status.Text=await Task.Run(()=>Core.Clean(rows));cleanGrid.ItemsSource=null;cleanSummary.Text=status.Text;}
  async Task Organize(){Commit(fileGrid);var rows=fileGrid.ItemsSource as List<FileRow>;if(rows==null||!rows.Any(x=>x.Selected))return;if(Confirm("Переместить "+rows.Count(x=>x.Selected)+" файлов в папку «Разобрано»?")){status.Text=await Task.Run(()=>Core.Organize(rows));fileGrid.ItemsSource=null;}}
  async Task Processes(){processGrid.ItemsSource=await Task.Run(()=>Core.Processes());}
  async Task CloseProcess(){var row=processGrid.SelectedItem as ProcessRow;if(row==null)return;using(var p=Process.GetProcessById(row.PID)){if(p.Id==Process.GetCurrentProcess().Id||p.StartTime.ToUniversalTime()!=row.Started||p.MainWindowHandle==IntPtr.Zero)throw new Exception("Нельзя закрыть этот процесс: нет обычного окна или процесс изменился.");if(Confirm("Попросить «"+row.Name+"» закрыться? Сначала сохраните работу.")){status.Text=p.CloseMainWindow()?"Приложению отправлен запрос закрытия. Подтвердите сохранение в его окне.":"Приложение не приняло запрос закрытия.";}}await Processes();}
  async Task Refresh(){snapshot=await Core.ReadStats();cpuValue.Text=snapshot.CPU<0?"—":snapshot.CPU.ToString("0")+"%";cpuHint.Text="Загрузка процессора";cpuBar.Value=Math.Max(0,snapshot.CPU);ramValue.Text=snapshot.Load+"%";ramHint.Text=Core.Size(snapshot.Total-snapshot.Free)+" из "+Core.Size(snapshot.Total);ramBar.Value=snapshot.Load;gpu.Text=snapshot.GPU;
   var fields=snapshot.GPU.Split('\n')[0].Split(',');double used,total;if(fields.Length>=6&&Double.TryParse(fields[1],NumberStyles.Float,CultureInfo.InvariantCulture,out used)&&Double.TryParse(fields[2],NumberStyles.Float,CultureInfo.InvariantCulture,out total)&&total>0){vramValue.Text=(used/1024).ToString("0.0")+" ГБ";vramHint.Text="из "+(total/1024).ToString("0.0")+" ГБ • GPU "+fields[3].Trim()+"%";vramBar.Value=100*used/total;}else{vramValue.Text="—";vramHint.Text="Нет данных NVIDIA";vramBar.Value=0;}
   try{var d=new DriveInfo(Path.GetPathRoot(Environment.SystemDirectory));diskValue.Text=Core.Size(d.AvailableFreeSpace);diskHint.Text=d.Name+" • из "+Core.Size(d.TotalSize);diskBar.Value=100.0*d.AvailableFreeSpace/d.TotalSize;}catch{diskValue.Text="—";}
   recommendations.Text=Core.Advice(snapshot);trend.Add(snapshot.CPU,snapshot.Load);subtitle.Text="Обновлено "+DateTime.Now.ToString("HH:mm:ss")+"   •   Локальная диагностика";floatText.Text="RAM "+snapshot.Load+"%   CPU "+cpuValue.Text+"\nVRAM "+vramValue.Text+"  "+vramHint.Text;report.Text=Report();}
  string Report(){if(snapshot==null)return "Дождитесь измерения.";return "PC Care Studio 1.0 • "+DateTime.Now.ToString("s")+"\nCPU: "+cpuValue.Text+"; RAM: "+ramHint.Text+" ("+snapshot.Load+"%)\nNVIDIA (модель, VRAM занято/всего МБ, GPU %, °C, драйвер): "+snapshot.GPU+"\n"+snapshot.Disks+"\n"+hardwareText+"\n"+Core.Advice(snapshot);}
  Task Export(){var d=new SaveFileDialog{Filter="Текстовый отчёт|*.txt",FileName="PC-Care-report.txt"};if(d.ShowDialog(this)==true)File.WriteAllText(d.FileName,Report()+"\n\nНакопители:\n"+health.Text+"\n\nОбновления:\n"+updates.Text,Encoding.UTF8);return Done();}
  Uri ComfyUri(){Uri u;if(!Uri.TryCreate(comfy.Text.Trim().TrimEnd('/')+"/",UriKind.Absolute,out u)||(u.Scheme!="http"&&u.Scheme!="https")||!String.IsNullOrEmpty(u.UserInfo))throw new Exception("Некорректный адрес ComfyUI.");return u;}
  async Task<bool> ComfyIdle(Uri u){using(var response=await http.GetAsync(new Uri(u,"queue"))){response.EnsureSuccessStatusCode();var q=Core.Json.Deserialize<Dictionary<string,object>>(await response.Content.ReadAsStringAsync());return q.ContainsKey("queue_running")&&q.ContainsKey("queue_pending")&&((System.Collections.ICollection)q["queue_running"]).Count==0&&((System.Collections.ICollection)q["queue_pending"]).Count==0;}}
  async Task FreeComfy(){var u=ComfyUri();if(!await ComfyIdle(u))throw new Exception("Очередь ComfyUI не пуста. Дождитесь окончания генерации.");if(!Confirm("Выгрузить модели ComfyUI? Следующая генерация будет загружать их повторно."))return;if(!await ComfyIdle(u))throw new Exception("В ComfyUI появилась задача; выгрузка отменена.");using(var r=await http.PostAsync(new Uri(u,"free"),new StringContent("{\"unload_models\":true,\"free_memory\":true}",Encoding.UTF8,"application/json"))){r.EnsureSuccessStatusCode();status.Text="ComfyUI принял запрос. Проверьте изменение занятой VRAM.";}Save();}
  async Task BackgroundClean(){int minutes=interval.SelectedItem is int?(int)interval.SelectedItem:30;if(auto.IsChecked!=true||DateTime.UtcNow-lastAuto<TimeSpan.FromMinutes(minutes))return;lastAuto=DateTime.UtcNow;if(snapshot==null||snapshot.CPU<0||snapshot.CPU>40||snapshot.Load>85)return;foreach(string l in snapshot.GPU.Split('\n')){double use;var f=l.Split(',');if(f.Length<6||!Double.TryParse(f[3],NumberStyles.Float,CultureInfo.InvariantCulture,out use)||use>30){status.Text="Автоочистка отложена: GPU занят или данные недоступны.";return;}}
   // Claim the action gate before awaiting a queue check so manual actions cannot race it.
   busy=true;try{if(protect.IsChecked==true){try{if(!await ComfyIdle(ComfyUri()))return;}catch{status.Text="Автоочистка отложена: нет связи с ComfyUI.";return;}}status.Text=await Task.Run(()=>Core.Clean(Core.Scan()));cleanGrid.ItemsSource=null;}finally{busy=false;}}
  void UpdateAccount(){accountText.Text=ai.Account==null?"ChatGPT не подключён":("Аккаунт: "+(String.IsNullOrEmpty(ai.Account.Email)?"подключён":ai.Account.Email));}
  async Task SignIn(){using(requestCancellation=new CancellationTokenSource()){status.Text="Завершите вход на сайте OpenAI. Кнопка остановки отменяет ожидание.";await ai.SignIn(requestCancellation.Token);provider.SelectedIndex=0;UpdateAccount();status.Text="ChatGPT подключён. Загрузите список моделей.";}requestCancellation=null;}
  async Task SignOut(){if(!Confirm("Выйти из ChatGPT и удалить сохранённые токены на этом ПК?"))return;bool revoked=await ai.SignOut(CancellationToken.None);models.ItemsSource=null;history.Clear();chat.Clear();UpdateAccount();status.Text=revoked?"Выполнен выход из ChatGPT.":"Локальный выход выполнен; отзыв на сервере не подтверждён. Отключите приложение в настройках ChatGPT.";}
  async Task<string> Access(CancellationToken ct){if(provider.SelectedIndex==0)return await ai.Token(ct);if(String.IsNullOrWhiteSpace(key.Password))throw new Exception("Введите API-ключ или выберите вход через ChatGPT.");return key.Password.Trim();}
  async Task LoadModels(){using(requestCancellation=new CancellationTokenSource()){string token=await Access(requestCancellation.Token);models.ItemsSource=await ai.Models(token,requestCancellation.Token);status.Text="Список моделей получен. Выберите текстовую модель для диалога.";}requestCancellation=null;}
  async Task Ask(){if(String.IsNullOrWhiteSpace(manualModel.Text)||String.IsNullOrWhiteSpace(question.Text))throw new Exception("Выберите модель и напишите вопрос.");if(!Confirm("Отправить вопрос"+(consent.IsChecked==true?", показанный отчёт ПК":"")+" и историю этого диалога в OpenAI? Применяются лимиты выбранного способа подключения."))return;string input=question.Text+(consent.IsChecked==true?"\n\nОтчёт:\n"+Report():"");string asked=question.Text;bool plan=provider.SelectedIndex==0;using(requestCancellation=new CancellationTokenSource(TimeSpan.FromMinutes(3))){try{string token=await Access(requestCancellation.Token);chat.AppendText("\n\nВы: "+asked+"\nИИ: ");string answer=await ai.Ask(token,manualModel.Text.Trim(),input,plan,history,delta=>{chat.AppendText(delta);chat.ScrollToEnd();},requestCancellation.Token);history.Add(new Dictionary<string,string>{{"role","user"},{"content",input}});history.Add(new Dictionary<string,string>{{"role","assistant"},{"content",answer}});while(history.Count>8)history.RemoveAt(0);Save();status.Text="Ответ завершён. ИИ не выполнял действий на ПК.";}catch{chat.AppendText("\n[Ответ не завершён]");throw;}finally{requestCancellation=null;}}}
  void ShowFloating(){if(floating!=null){floating.Activate();return;}floating=new Window{Title="PC Care • монитор",Width=350,Height=310,MinWidth=280,MinHeight=200,Topmost=true,WindowStyle=WindowStyle.ToolWindow,Background=B("#121D2E"),Foreground=Foreground,ShowInTaskbar=false};var p=new StackPanel{Margin=new Thickness(16)};p.Children.Add(Txt("◈  PC CARE",20));p.Children.Add(floatText);p.Children.Add(Btn("Сканировать и очистить",async()=>{Restore();await Scan();}));p.Children.Add(Btn("Выгрузить модели ComfyUI",FreeComfy));p.Children.Add(Btn("ИИ-помощник",()=>{Restore();Select(5);return Done();}));floating.Content=new ScrollViewer{Content=p};floating.Closed+=delegate{floating=null;};floating.Show();}
  public async Task SmokeTest(string directory){Directory.CreateDirectory(directory);await Task.Delay(2000);for(int i=0;i<tabs.Items.Count;i++){Select(i);UpdateLayout();await Task.Delay(150);if(i==0||i==1||i==5){var bmp=new RenderTargetBitmap((int)ActualWidth,(int)ActualHeight,96,96,PixelFormats.Pbgra32);bmp.Render(this);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bmp));using(var s=File.Create(Path.Combine(directory,"screen-"+i+".png")))encoder.Save(s);}}Select(0);quitting=true;Close();}
 }
